const body = $input.first().json.body || $input.first().json;
const quoteId = 'QM-' + Date.now();
const now = new Date().toISOString();

const quote = {
  ...body,
  id: quoteId,
  createdAt: now,
  updatedAt: now
};

// Get existing quotes from workflow static data
const staticData = $getWorkflowStaticData('global');
if (!staticData.quotes) {
  staticData.quotes = {};
}

// Save the quote
staticData.quotes[quoteId] = quote;

return { json: { success: true, quote } };

const webhook = $input.first().json;
const userId = webhook.query?.userId;

// Get quotes from workflow static data
const staticData = $getWorkflowStaticData('global');
const allQuotes = staticData.quotes || {};

// Convert to array and filter by userId if provided
let quotes = Object.values(allQuotes);

if (userId) {
  quotes = quotes.filter(q => q.userId === userId);
}

// Sort by creation date (newest first)
quotes.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));

return { json: { success: true, quotes } };

const webhook = $input.first().json;
const quoteId = webhook.params?.id;

// Get quotes from workflow static data
const staticData = $getWorkflowStaticData('global');
const quote = staticData.quotes?.[quoteId];

if (!quote) {
  return { json: { success: false, error: 'Quote not found' } };
}

return { json: { success: true, quote } };

const webhook = $input.first().json;
const quoteId = webhook.params?.id;
const updates = webhook.body || {};

// Get quotes from workflow static data
const staticData = $getWorkflowStaticData('global');

if (!staticData.quotes?.[quoteId]) {
  return { json: { success: false, error: 'Quote not found' } };
}

// Update the quote
const existing = staticData.quotes[quoteId];
const updatedQuote = {
  ...existing,
  ...updates,
  id: existing.id,
  createdAt: existing.createdAt,
  updatedAt: new Date().toISOString()
};

staticData.quotes[quoteId] = updatedQuote;

return { json: { success: true, quote: updatedQuote } };

const webhook = $input.first().json;
const quoteId = webhook.params?.id;

// Get quotes from workflow static data
const staticData = $getWorkflowStaticData('global');

if (staticData.quotes?.[quoteId]) {
  delete staticData.quotes[quoteId];
}

return { json: { success: true, deleted: true } };
